import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateShippingProfilesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateShippingProfilesWorkflow(req.scope)
    .run({
      input: {
        selector: {
          id: "sp_123",
        },
        update: {
          name: "Standard",
        }
      }
    })

  res.send(result)
}

